async function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('egress-recognition-qa',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
