 root.classList.toggle('hidden',!notices.length);if(!notices.length){root.innerHTML='';return;}
 const n=notices[0],unknown=!stairLanding(floor().stairs.find(s=>s.id===n.id)||{}),count=a.circulationRoutes.length,partial=a.rooms.filter(r=>r.circulation?.state==='partial').length;
