if(kind==='void'){const base=p.floors.find(f=>f.id===o.baseFloorId),top=p.floors.find(f=>f.id===o.throughFloorId),options=(key)=>p.floors.map(f=>`<option value="${f.id}" ${o[key]===f.id?'selected':''}>${esc(f.name)} · ${fmt(f.elevation)}</option>`).join('');html+=`<label>Lowest occupied floor<select data-prop="baseFloorId">${options('baseFloorId')}</select></label><label>Highest floor WITHOUT a slab<select data-prop="throughFloorId">${options('throughFloorId')}</select></label><p class="small">The base retains its floor. Openings are cut in every level above it through the chosen top level. Shared XY footprint on all affected floors. Upper-floor routes avoid the opening; room areas and loads exclude it.</p><p class="small">${base&&top?p.floors.filter(f=>f.elevation>=base.elevation&&f.elevation<=top.elevation).length+' levels in the space':''} · footprint ${(area(o.points)/(p.units==='ft'?SF:1)).toFixed(1)} ${p.units==='ft'?'sf':'m²'}.<br>Smoke control, guards, atrium separation and structural support require separate review.</p>`;}
