function renderReferenceControls(){
 const im=target().image,fi=underlayIndex();
 $('#reference-controls').innerHTML=`${im?`<div class="reference-status ${im.calibrated?'':'unscaled'}">${esc(im.name)}<br><b>${im.calibrated?'Scale calibrated':'Scale not calibrated'}</b></div><button id="calibrate-reference">↔ Calibrate reference · 2 points</button>${mode==='building'?`<button id="recognize-reference" class="primary">AI · recognize rooms + circulation</button>${im.interpretation?'<button id="review-recognition">Check rooms & outdoors</button>':''}`:''}<button id="editable-reference" ${im.calibrated?'':'disabled'}>Trace image / PDF linework</button>`:''}${mode==='building'&&floor().cad.length?'<button id="recognize-cad">Recognize CAD spaces</button>':''}<button id="import-guide">Drawing units + import guide</button>${mode==='building'?`<button id="detect-rooms" ${floor().walls.length?'':'disabled'}>Detect rooms from editable walls</button><div class="reference-status">Shared XY coordinates · Z ${fmt(floor().elevation)}${floor().elevation===0?'<br>Ground floor + site in one view':''}</div>${p.floors.length>1?`<label>Reference floor<select id="underlay-floor"><option value="-1">None</option>${p.floors.map((f,i)=>i!==p.activeFloor?`<option value="${i}" ${fi===i?'selected':''}>${esc(f.name)} · ${fmt(f.elevation)}</option>`:'').join('')}</select></label><button id="align-floor">Align floor · 2 reference points</button>`:''}`:'<div class="reference-status">Edit site paths around the ground floor. Click an exit to edit the same building object.</div>'}`;
 if($('#calibrate-reference'))$('#calibrate-reference').onclick=()=>{setTool('calibrate');toast('Zoom in and pick both ends of a known dimension. Object/grid snaps are bypassed for calibration.');};
 $('#import-guide').onclick=importGuide;if($('#recognize-cad'))$('#recognize-cad').onclick=recognizeCad;if($('#editable-reference'))$('#editable-reference').onclick=traceReference;if($('#recognize-reference'))$('#recognize-reference').onclick=recognizeReference;if($('#review-recognition'))$('#review-recognition').onclick=()=>reviewRecognition(floor(),floor().image);if($('#detect-rooms'))$('#detect-rooms').onclick=detectRoomDialog;
 if($('#underlay-floor'))$('#underlay-floor').onchange=e=>{underlays.set(floor().id,Number(e.target.value));vis.underlay=true;renderPanels();};
 if($('#align-floor'))$('#align-floor').onclick=()=>{
  modal('Align floor by shared reference points',`<p>Use two matching column-grid intersections or surveyed control points. Overhangs and setbacks stay unchanged. Both floors must already have the correct scale.</p><label>Reference floor<select id="align-reference">${p.floors.map((f,i)=>i!==p.activeFloor?`<option value="${i}" ${fi===i?'selected':''}>${esc(f.name)}</option>`:'').join('')}</select></label><p class="callout">Pick A and B on the current floor, then the corresponding A and B on the blue reference floor. The whole current floor—including CAD, image, rooms, walls, doors and stairs—moves and rotates together. No scale change.</p><button id="align-start" class="primary">Pick corresponding points</button>`);
  $('#align-start').onclick=()=>{const reference=Number($('#align-reference').value);$('#modal').close();setTool('alignFloor');alignSession={reference};underlays.set(floor().id,reference);vis.underlay=true;allFloors=false;cameras.clear();const a=extent('building',p.activeFloor),b=extent('building',reference),loX=Math.min(a.minX,b.minX),loY=Math.min(a.minY,b.minY),hiX=Math.max(a.maxX,b.maxX),hiY=Math.max(a.maxY,b.maxY);cameras.set(floor().id,{x:(loX+hiX)/2,y:(loY+hiY)/2,s:Math.min((W-90)/Math.max(8,hiX-loX),(H-130)/Math.max(8,hiY-loY))});renderPanels();};
 };
}
function alignmentHint(){return ['Pick A on the CURRENT floor.','Pick B on the CURRENT floor.','Pick corresponding A on the BLUE REFERENCE floor.','Pick corresponding B on the BLUE REFERENCE floor.'][draft.length]||'Review floor alignment.';}
