if(v.mode!=='site')append(p.floors[v.fi]);if(vis.voids)for(const o of floorOpenings(p,v.fi,{includeBase:true}))append({obstacles:[o]},{obstacles:true});if((v.mode==='ground'||v.mode==='site')&&vis.site)append(p.site);
