$('#scope-btn').onclick=()=>modal('Check scope + sources',`<p><b>Studio plan analysis · indoors and outdoors.</b> Selected IBC 2021 A/B/E/M rules and ADA walking-surface criteria support plan design decisions. Local amendments are not applied automatically.</p><ul><li>Sampled exit-access travel and geometric connectivity</li><li>Occupant-load calculations using the selected function and area basis</li><li>Door clear widths, basic exit separation and load-based doorway counts</li><li>Linked protected-stair assumptions and ground-floor connections to the public way</li><li>Manually traced common paths and dead ends</li><li>Selected ADA walking-route width/slope checks and pedestrian–vehicle crossing review</li></ul><p>The Code tab groups room loads, doors and swings, corridor widths, exit arrangement, traced common paths and dead ends, stair connections, outdoor discharge paths, egress courts and accessible walking routes. Site width checks use assigned ground-floor exit loads; merged and multi-floor discharge remain explicit review items. Route playback illustrates connections.</p><div class="source-list"><p><a href="${sources.ibc}" target="_blank" rel="noopener">ICC · 2021 IBC Means of Egress ↗</a><br><a href="${sources.ada}" target="_blank" rel="noopener">U.S. Access Board · ADA Chapter 4 ↗</a><br><a href="https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books" target="_blank" rel="noopener">Michigan adopted codes ↗</a><br><a href="./THIRD_PARTY.md" target="_blank">CAD decoder licenses + source ↗</a></p></div>`);
function circulationReport(project,result){
 const rows=result.floors.flatMap((f,fi)=>(f.circulationRoutes||[]).map(r=>({...r,floor:project.floors[fi].name})));
 if(!rows.length)return '';
 return `<h2>Circulation to stairs not assigned as exits</h2><p>Amber paths end at the stair landing on the listed floor. They do not establish an eligible exit, a complete building-to-site route or an egress-capacity allocation.</p><table><tr><th>Floor / space</th><th>Landing</th><th>On-floor distance</th><th>Coverage</th></tr>${rows.map(r=>`<tr><td>${esc(r.floor)} / ${esc(r.name)}</td><td>${esc(r.stairName)}</td><td>${fmt(r.distance)}</td><td>${r.partial?'Only the reachable portion; inspect disconnected areas':'Sampled room area reaches the landing; this stair is not assigned as an exit'}</td></tr>`).join('')}</table>`;
}
$('#report-btn').onclick=()=>{if(p.floors.some(recognitionProblem))return toast('Recognition is incomplete. Area and egress reports are unavailable until the wall geometry is resolved.');if(!analysis||analyzedRevision!==revision)return toast('Wait for the current design checks before exporting.');const image=canvas.toDataURL('image/png'),complete=analysis.complete;const html=`<!doctype html><html><head><title>${esc(p.name)} — Egress + Site report</title><style>body{font:12px/1.6 Arial,sans-serif;color:#26352f;margin:35px}h1{font-size:26px}h2{margin-top:28px;border-bottom:1px solid #ccc}table{border-collapse:collapse;width:100%;font-size:11px}td,th{border:1px solid #ddd;padding:7px;text-align:left;vertical-align:top}th{background:#edf2ea}.fail{color:#a54035}.review{color:#937023}.pass{color:#2c6a49}.input{color:#407ba4}img{width:100%;max-height:550px;object-fit:contain}button{padding:12px}@media print{button,.print-note{display:none}h2,h3{break-after:avoid}tr{break-inside:avoid}}</style></head><body><button onclick="window.print()">Save as PDF on this device</button><p class="print-note">Choose “Save as PDF” in the print window. Keep editing your design in the lab: moving walls, changing room use and adjusting doors updates the analysis. This PDF records the current version.</p><h1>${esc(p.name)}</h1><p>Egress + Site Lab · ${new Date().toLocaleString()}<br>IBC 2021 teaching subset · ${p.settings.sprinkler?'NFPA 13 throughout assumed':'No full sprinkler allowance'} · ${p.settings.voice?'Voice/alarm assumed':'No voice/alarm reduction'}<br>Studio analysis of indoor and outdoor plans; results apply to the listed geometry, rules and assumptions.</p><img src="${image}" alt="Design overview">${precedentSourcesHtml(p)}${doorScheduleReport(p)}${planCodeReport(p,analyzePlanCode(p,analysis))}${circulationReport(p,analysis)}<h2>Complete building-to-site routes</h2><table><tr><th>Floor / room</th><th>Connection</th><th>Total route</th></tr>${complete.map(r=>`<tr><td>${esc(p.floors[r.floor].name)} / ${esc(r.name)}</td><td>${r.complete?'Connected to public way':esc(r.reason||'Connection requires review')}</td><td>${r.distance==null?'No verified route':fmt(r.distance)+(r.exitAccessComplete?'':' — reachable portion only')}</td></tr>`).join('')}</table>${analysis.floors.map((r,i)=>`<h2>${esc(p.floors[i].name)}</h2><p>${p.floors[i].pendingSpaces?.length?'INCOMPLETE MODEL — '+p.floors[i].pendingSpaces.length+' spaces are missing wall enclosures. '+r.total+' occupants counted in enclosed spaces only':r.total+' design occupants'} · ${r.exits} identified exits · analysis grid ${fmt(r.gridStep||0)}</p><h3>Room area → design occupant load</h3><p>${occupantMethod} Calculations use unrounded areas and factors.</p><table><tr><th>Space / use</th><th>Area and basis</th><th>Area per person / source</th><th>Calculated people</th><th>Input review</th></tr>${r.rooms.map(o=>`<tr><td>${esc(o.name)}<br>${esc(o.functionLabel)}</td><td>${(o.area/SF).toFixed(1)} sf / ${o.area.toFixed(2)} m²<br>${esc(o.basis)}</td><td>${o.role==='corridor'?'No additional occupants':factorText(o.factor)+'<br>'+factorReference(o)}</td><td>${o.occupants}<br><small>${esc(loadCalculation(o))}</small></td><td>${o.areaConfirmed?'Area basis confirmed':'Confirm use, net/gross basis and scale'}</td></tr>`).join('')}</table><h3>Doors, corridors and stairs → width bottlenecks</h3><p>${esc(r.capacity?.method||'Route allocation unavailable.')} Required width is the greater of the component minimum and served occupants × capacity factor. Stair requirements are evaluated per story.</p><table><tr><th>Component / source rooms</th><th>Modeled people</th><th>Provided width</th><th>Required width</th><th>Shortfall / action</th></tr>${(r.capacity?.rows||[]).map(o=>`<tr><td>${esc(o.name)} · ${esc(o.kind)}<br>${o.sources.map(esc).join(', ')}</td><td>${o.allocationKnown||o.corridorServed>0?o.load:'Unresolved'}${o.corridorServed!=null?'<br>Corridor total: '+o.corridorServed:''}</td><td>${o.available==null?'Not measured':capfmt(o.available)}<br>${esc(o.widthSource)}</td><td>${o.allocationKnown||o.corridorServed>0?capfmt(o.required,true):'Allocation needed'}<br>${o.kind==='passage'?'Flow estimate only; component minimum unverified':'Minimum '+capfmt(o.minimum,true)}; ${o.factor} in/person</td><td class="${o.status}">${o.shortfall>0?'Short by '+capfmt(o.shortfall,true)+' — widen or revise allocation':'REVIEW: confirm clear width and allocation'}</td></tr>`).join('')}</table><h3>Checks and design actions</h3><table><tr><th>Status</th><th>Check</th><th>Evidence / next step</th><th>Reference</th></tr>${r.checks.map(c=>`<tr><td class="${c.status}">${c.status.toUpperCase()}</td><td>${esc(c.title)}</td><td>${esc(c.detail)}</td><td>${esc(c.ref)}</td></tr>`).join('')}</table>`).join('')}<h2>Design revision priorities</h2><p>Resolve flagged checks first. Review items identify missing inputs or unverified conditions; they do not establish a pass. Use each finding’s evidence / next step to modify the design online. Checks update automatically as room geometry, use, doors and corridors change. Export a new PDF to record the revised scheme.</p><h2>Source drawings</h2>${p.floors.map(f=>`<p>${esc(f.name)}: ${[f.image?esc(f.image.name)+'; scale '+(f.image.calibrated?'calibrated':'NOT calibrated'):'',...(f.imports||[]).map(i=>esc(i.name)+'; omitted: '+esc(JSON.stringify(i.ignored)))].filter(Boolean).join('<br>')||'Drawn in app'}</p>`).join('')}<h2>Area basis + IBC factors</h2>${occupantReferenceTable()}<h2>References</h2><p><a href="${sources.ibc}">ICC 2021 IBC Means of Egress</a><br><a href="${sources.ada}">ADA Chapter 4</a></p></body></html>`;const win=window.open('','_blank');if(win){win.document.open();win.document.write(html);win.document.close();}else download(new Blob([html],{type:'text/html'}),'egress-report.html');};
