$('#occupant-factors').onclick=()=>{
 const loads=floor().rooms.map(r=>roomLoad(p,p.activeFloor,r));
 modal('Room areas + occupant loads',`<p>${occupantMethod}</p>${loads.length?`<table class="occupant-table"><thead><tr><th>Room / use</th><th>Area / basis</th><th>Area per person</th><th>Design load</th></tr></thead><tbody>${loads.map(r=>`<tr><td><button data-load-room="${esc(r.id)}">${esc(r.name)}</button><br>${esc(r.functionLabel)}</td><td>${r.area.toFixed(2)} m²<br>${(r.area/SF).toFixed(1)} sf · ${esc(r.basis)}</td><td>${r.role==='corridor'?'No added occupants':factorText(r.factor)}<br><small>${factorReference(r)}</small></td><td>${r.occupants} people<br><small>${esc(loadCalculation(r))}</small></td></tr>`).join('')}</tbody></table><p>Click a room name to edit its use and area basis.</p>`:'<p>Draw or create editable rooms to see their occupant loads here.</p>'}<details><summary>IBC 2021 Table 1004.5 · area-per-person reference</summary>${occupantReferenceTable()}</details>`);
 $$('[data-load-room]').forEach(b=>b.onclick=()=>{selected=b.dataset.loadRoom;$('#modal').close();renderPanels();switchTab('properties');});
};
